 a[1]:=1;
 if i mod 2 =0 then a[i]:=a[i-1]+a[i-2]+a[i div 2];
 if i mod 2 =1 then a[i]:=a[i-1]+a[i-2];
 end;
 for i:=1 to 9 do
 a[i]:=0;
 for i:=11 to 12 do begin
 if i mod 2 =0 then a[i]:=a[i-1]+a[i-2]+a[i div 2];
 if i mod 2 =1 then a[i]:=a[i-1]+a[i-2];
 end;
 println(a[12])
end.
